// Explainer sections: tables and charts filled from project.js / model.js / replay.js
// (all generated by training/export_web.py from the current model and data).
(function () {
  "use strict";

  var M = window.ESP32_MODEL, PR = window.ESP32_PROJECT, R = window.ESP32_REPLAY, Pipe = window.Esp32Pipeline;
  var F = window.Esp32Fmt, svg = F.svg, html = F.html, clear = F.clear;
  var P = M.params;
  var $ = function (id) { return document.getElementById(id); };

  function rows(tbodyParent, data) {
    var tb = tbodyParent.querySelector("tbody");
    data.forEach(function (cells) {
      var tr = html("tr", "", null, tb);
      cells.forEach(function (c) { html("td", "", String(c), tr); });
    });
  }

  // ── Data quality + training tables ────────────────────────────────────────
  rows($("quality-table"), PR.captures.map(function (c) {
    return [c.name, c.kind === "normal" ? "training" : "test", c.minutes, c.rows.toLocaleString(), c.timeouts,
            c.blind_zone, c.over_range, c.gaps];
  }));
  rows($("train-table"), PR.training.map(function (t) {
    return [t.name, t.valid.toLocaleString(), t.contaminated + " (" + (100 * t.contaminated / t.valid).toFixed(1) + "%)",
            t.kept.toLocaleString()];
  }));
  var FEAT = [["distance", "cm", "where the object normally sits"], ["jitter", "cm", "normal noise level"],
              ["rate of change", "cm/s", "normal movement"], ["variance", "cm²", "normal spread"]];
  rows($("norm-table"), FEAT.map(function (f, i) {
    var lo = M.norm_min[i], hi = lo + 1 / M.norm_scale[i];
    return [f[0], lo.toFixed(2) + " " + f[1], hi.toFixed(2) + " " + f[1], f[2]];
  }));

  // ── Cleaning steps (numbers straight from the exported parameters) ────────
  var steps = [
    ["Validity gate", "Keep readings in " + P.VALID_MIN_CM + "–" + P.VALID_MAX_CM + " cm. Timeouts (−1), blind-zone ringing, " +
      "over-range and NaN are dropped. " + P.FAULT_INVALID_COUNT + " invalid readings in a row (~" +
      (P.FAULT_INVALID_COUNT * P.SAMPLE_INTERVAL_MS / 1000) + " s) raise a sensor fault."],
    ["Gap reset", "More than " + P.MAX_GAP_MS + " ms without a valid reading (sensor blocked, reboot): " +
      "the filter history is stale, so it is cleared and features restart cleanly."],
    ["Hampel spike filter", "Over the last " + P.HAMPEL_SIZE + " valid readings (" + (P.HAMPEL_SIZE * P.SAMPLE_INTERVAL_MS / 1000) +
      " s): replace a reading with the median only if it is more than max(" + P.HAMPEL_K_MAD.toFixed(2) + "·MAD, " + P.HAMPEL_MIN_CM +
      " cm) away. That is 3 robust standard deviations. Ghost echoes are removed, real motion passes."],
    ["Window features", "Over the last " + P.WINDOW_SIZE + " filtered readings (" + (P.WINDOW_SIZE * P.SAMPLE_INTERVAL_MS / 1000) +
      " s): distance, jitter (std dev), rate of change (|Δ|/s), variance. Then normalize with the training min/range."],
    ["…then after the model: debounce", P.ALARM_ON_COUNT + " anomalous samples in a row raise the alarm, " + P.ALARM_OFF_COUNT +
      " normal ones clear it. A single noisy sample never lights the LED."],
  ];
  steps.forEach(function (s) {
    var li = html("li", "", null, $("clean-steps"));
    html("b", "", s[0] + ": ", li);
    li.appendChild(document.createTextNode(s[1]));
  });

  // ── Shared small-chart helpers ────────────────────────────────────────────
  var MG = { l: 48, r: 70, t: 14, b: 26 };
  function sizeSvg(el, H) {
    var W = Math.max(280, Math.floor(el.parentNode.clientWidth));
    el.setAttribute("width", W); el.setAttribute("height", H); el.setAttribute("viewBox", "0 0 " + W + " " + H);
    clear(el);
    return W;
  }
  function tooltip(stack) {
    var t = html("div", "tooltip", null, stack);
    t.hidden = true;
    return t;
  }
  function placeTip(tip, stack, px, py) {
    tip.hidden = false;
    var w = tip.offsetWidth;
    tip.style.left = Math.max(0, px + 14 + w > stack.clientWidth ? px - 14 - w : px + 14) + "px";
    tip.style.top = Math.max(0, py - 20) + "px";
  }
  function tipRow(tip, val, label, key) {
    var d = html("div", "tt-row", null, tip);
    if (key) html("span", "key " + key, null, d);
    html("b", "", val, d);
    html("span", "", label, d);
  }

  // ── Hampel vs median on a real vibration excerpt from the replay ──────────
  var hampelData = (function () {
    var i0 = -1, k;
    for (k = 0; k < R.ts.length; k++) if (R.label[k] && R.scenarios[R.scen[k]] === "vibration") { i0 = k; break; }
    if (i0 < 0) return null;
    var a = Math.max(0, i0 - 15), b = Math.min(R.ts.length - 1, i0 + 45);
    var pre = new Pipe.Preprocessor(P), medBuf = [], out = [];
    for (k = 0; k <= b; k++) {
      var f = pre.push(R.raw[k], R.ts[k]);
      var valid = f !== null, med = null;
      if (valid) {
        medBuf.push(R.raw[k]); if (medBuf.length > 5) medBuf.shift();
        var s = medBuf.slice().sort(function (p, q) { return p - q; });
        med = s[s.length >> 1];
      }
      if (k >= a) out.push({ t: (R.ts[k] - R.ts[a]) / 1000, raw: R.raw[k], valid: valid, hampel: valid ? f[0] : null, median: med });
    }
    return { pts: out, startS: (R.ts[i0] - R.ts[a]) / 1000, atS: (R.ts[i0] - R.ts[0]) / 1000 };
  })();
  if (hampelData) $("hampel-caption").textContent = "Excerpt of the replay capture: a ±3 cm, 1.7 Hz vibration starts " +
    hampelData.startS.toFixed(1) + " s into this window (t = " + hampelData.atS.toFixed(0) + " s in the file). Same raw readings, two filters.";

  function drawHampel() {
    var el = $("chart-hampel"), H = 230, W = sizeSvg(el, H), d = hampelData;
    if (!d) return;
    var pts = d.pts, tMax = pts[pts.length - 1].t, lo = Infinity, hi = -Infinity;
    pts.forEach(function (p) { if (p.valid) { lo = Math.min(lo, p.hampel, p.median); hi = Math.max(hi, p.hampel, p.median); } });
    lo = Math.floor(lo - 1); hi = Math.ceil(hi + 1);
    var pw = W - MG.l - MG.r, ph = H - MG.t - MG.b;
    var x = function (t) { return MG.l + t / tMax * pw; };
    var y = function (v) { return MG.t + (1 - (v - lo) / (hi - lo)) * ph; };
    var yc = function (v) { return Math.max(MG.t, Math.min(H - MG.b, y(v))); };
    for (var v = lo; v <= hi; v += (hi - lo > 12 ? 4 : 2)) {
      svg("line", { x1: MG.l, x2: W - MG.r, y1: y(v), y2: y(v), class: "grid-line" }, el);
      svg("text", { x: MG.l - 6, y: y(v) + 3.5, "text-anchor": "end", class: "tick-label" }, el).textContent = v + " cm";
    }
    for (var s = 0; s <= tMax; s += 2) svg("text", { x: x(s), y: H - 8, "text-anchor": "middle", class: "tick-label" }, el).textContent = s + " s";
    svg("line", { x1: MG.l, x2: W - MG.r, y1: H - MG.b, y2: H - MG.b, class: "axis-line" }, el);
    var vx = x(d.startS);
    svg("rect", { x: vx, y: MG.t, width: W - MG.r - vx, height: ph, class: "band-fault", opacity: 0.6 }, el);
    svg("text", { x: vx + 6, y: MG.t + 12, class: "direct-label" }, el).textContent = "vibration on";

    var dots = "", lh = "", lm = "";
    pts.forEach(function (p) {
      if (!p.valid) return;
      dots += "M" + (x(p.t) - 1.8).toFixed(1) + " " + yc(p.raw).toFixed(1) + "a1.8 1.8 0 1 0 3.6 0a1.8 1.8 0 1 0 -3.6 0";
      lh += (lh ? "L" : "M") + x(p.t).toFixed(1) + " " + y(p.hampel).toFixed(1);
      lm += (lm ? "L" : "M") + x(p.t).toFixed(1) + " " + y(p.median).toFixed(1);
    });
    svg("path", { d: dots, class: "raw-dots" }, el);
    svg("path", { d: lm, class: "line-s2" }, el);
    svg("path", { d: lh, class: "line-s1" }, el);
    var last = pts[pts.length - 1];
    svg("text", { x: W - MG.r + 6, y: y(last.hampel) - 4, class: "direct-label" }, el).textContent = "Hampel-7";
    svg("text", { x: W - MG.r + 6, y: y(last.median) + 12, class: "direct-label" }, el).textContent = "median-5";

    var cross = svg("line", { class: "crosshair", display: "none", y1: MG.t, y2: H - MG.b }, el);
    var stack = el.parentNode, tip = stack.querySelector(".tooltip") || tooltip(stack);
    el.onpointermove = function (e) {
      var px = e.clientX - el.getBoundingClientRect().left, t = (px - MG.l) / pw * tMax, best = null;
      pts.forEach(function (p) { if (!best || Math.abs(p.t - t) < Math.abs(best.t - t)) best = p; });
      if (!best || px < MG.l || px > W - MG.r) { el.onpointerleave(); return; }
      cross.setAttribute("display", "inline"); cross.setAttribute("x1", x(best.t)); cross.setAttribute("x2", x(best.t));
      clear(tip);
      html("div", "tt-head", "t = " + best.t.toFixed(1) + " s", tip);
      tipRow(tip, best.raw < 0 ? "no echo" : best.raw.toFixed(2) + " cm", "raw", "key-dot");
      if (best.valid) {
        tipRow(tip, best.hampel.toFixed(2) + " cm", "Hampel-7", "key-line s1");
        tipRow(tip, best.median.toFixed(2) + " cm", "median-5", "key-line s2");
      }
      placeTip(tip, stack, x(best.t), 40);
    };
    el.onpointerleave = function () { cross.setAttribute("display", "none"); tip.hidden = true; };
  }

  // ── Threshold histogram (two panels, shared log-MSE axis) ─────────────────
  function drawHist() {
    var el = $("chart-hist"), H = 300, W = sizeSvg(el, H), h = PR.hist, E = h.edges;
    var mg = { l: 44, r: 12, t: 22, b: 30 }, gap = 34;
    var pw = W - mg.l - mg.r, panelH = (H - mg.t - mg.b - gap) / 2;
    var x = function (lv) { return mg.l + (lv - E[0]) / (E[E.length - 1] - E[0]) * pw; };
    var panels = [
      { key: "normal_train", cls: "hist-bar-n", title: "Normal data (training, after cleaning)", top: mg.t },
      { key: "test_anomaly", cls: "hist-bar-a", title: "Anomalous test samples (excl. sensor faults)", top: mg.t + panelH + gap },
    ];
    var stack = el.parentNode, tip = stack.querySelector(".tooltip") || tooltip(stack);
    panels.forEach(function (p) {
      var counts = h[p.key], total = counts.reduce(function (a, b) { return a + b; }, 0);
      var share = counts.map(function (c) { return 100 * c / total; });
      var maxS = Math.max.apply(null, share), yMax = Math.ceil(maxS / 10) * 10;
      var y = function (v) { return p.top + panelH - v / yMax * panelH; };
      svg("text", { x: mg.l, y: p.top - 8, class: "axis-title" }, el).textContent = p.title + " · n = " + total.toLocaleString();
      [0, yMax / 2, yMax].forEach(function (v) {
        svg("line", { x1: mg.l, x2: W - mg.r, y1: y(v), y2: y(v), class: v ? "grid-line" : "axis-line" }, el);
        svg("text", { x: mg.l - 6, y: y(v) + 3.5, "text-anchor": "end", class: "tick-label" }, el).textContent = v + "%";
      });
      share.forEach(function (s, i) {
        if (!counts[i]) return;
        var x0 = x(E[i]) + 1, w = Math.max(1, x(E[i + 1]) - x(E[i]) - 2), top = y(s);
        var bar = svg("rect", { x: x0, y: top, width: w, height: Math.max(1, p.top + panelH - top), rx: Math.min(2, w / 2), class: p.cls }, el);
        var hit = svg("rect", { x: x(E[i]), y: p.top, width: x(E[i + 1]) - x(E[i]), height: panelH, fill: "transparent" }, el);
        hit.addEventListener("pointermove", function () {
          clear(tip);
          html("div", "tt-head", "MSE " + F.pow10(E[i]) + " to " + F.pow10(E[i + 1]), tip);
          tipRow(tip, s.toFixed(1) + "%", "of samples (" + counts[i].toLocaleString() + ")", p.cls === "hist-bar-n" ? "key-line s1" : "key-line s2");
          placeTip(tip, stack, x0 + w, top);
          bar.style.opacity = 0.75;
        });
        hit.addEventListener("pointerleave", function () { tip.hidden = true; bar.style.opacity = ""; });
      });
    });
    for (var lv = -4; lv <= 8; lv += 2) {
      svg("text", { x: x(lv), y: H - 10, "text-anchor": "middle", class: "tick-label" }, el).textContent = lv === 0 ? "1" : F.pow10(lv);
    }
    var tx = x(Math.log10(M.threshold));
    svg("line", { x1: tx, x2: tx, y1: mg.t - 4, y2: H - mg.b, class: "thr-line" }, el);
    svg("text", { x: tx + 5, y: mg.t + 12, class: "thr-label" }, el).textContent = "threshold " + M.threshold.toFixed(3);
  }

  // ── Results ───────────────────────────────────────────────────────────────
  function range(v) {
    if (!v.length) return "–";
    var a = Math.min.apply(null, v).toFixed(1), b = Math.max.apply(null, v).toFixed(1);
    return (a === b ? a : a + "–" + b) + " s";
  }
  (function results() {
    var all = [], fa = 0, mins = 0;
    PR.results.forEach(function (r) { all = all.concat(r.events); fa += r.false_alarms; mins += r.normal_minutes; });
    var det = all.filter(function (e) { return e.detected; });
    var lat = det.map(function (e) { return e.latency_ms / 1000; });
    var kp = [
      [det.length + " / " + all.length, "events detected"],
      [range(lat), "detection latency"],
      [String(fa), "false alarms in " + mins.toFixed(0) + " min of normal data"],
      [PR.results.length + " files", PR.results.map(function (r) { return r.name; }).join(", ")],
    ];
    kp.forEach(function (k) {
      var d = html("div", "kpi", null, $("result-kpis"));
      html("div", "kpi-val", k[0], d);
      html("div", "kpi-label", k[1], d);
    });
    var by = {}, order = [];
    all.forEach(function (e) {
      if (!by[e.scenario]) { by[e.scenario] = []; order.push(e.scenario); }
      by[e.scenario].push(e);
    });
    var how = { sensor_fault: "invalid-reading counter", vibration: "model: jitter, variance, rate" };
    var tb = $("scen-table").querySelector("tbody");
    order.forEach(function (s) {
      var ev = by[s], d = ev.filter(function (e) { return e.detected; });
      var l = d.map(function (e) { return e.latency_ms / 1000; });
      var tr = html("tr", "", null, tb);
      html("td", "", s.replace(/_/g, " "), tr);
      html("td", d.length === ev.length ? "yes" : "no", d.length + " / " + ev.length, tr);
      html("td", "", range(l), tr);
      html("td", "", how[s] || "model: distance", tr);
    });
  })();

  function drawAll() { drawHampel(); drawHist(); }
  var rt = null;
  window.addEventListener("resize", function () { clearTimeout(rt); rt = setTimeout(drawAll, 120); });
  drawAll();
})();
